#' Chi-Square Post-Hoc Tests
#'
#' Performs Chi-Square test and post-hoc pairwise comparisons. Post-hoc 
#' pairwise comparisons are ONLY performed when the overall chi-square test is 
#' significant (p < alpha). This enforces proper statistical workflow and 
#' prevents data dredging. Selecting 'None' for post-hoc method DISABLES all 
#' pairwise testing. If you want unadjusted pairwise comparisons, this feature 
#' is not available (by design, as it would encourage inappropriate multiple 
#' testing). The chi-square statistic, the pairwise p-values and their 
#' adjustment are checked against base R (chisq.test, fisher.test, p.adjust) 
#' in the package tests. Read the pairwise results together with the effect 
#' sizes and the residuals, not from the p-values alone.
#' 
#'
#' @examples
#' \donttest{
#' # Tumour grade by treatment group, using the histopathology data
#' # bundled with the module. The overall test is significant
#' # (p = 0.010) and the three grade levels give three pairwise
#' # comparisons, so the post-hoc table is populated.
#' chisqposttest(
#'     data = histopathology,
#'     rows = "Grade_Level",
#'     cols = "Group")
#'}
#' @param data The data as a data frame.
#' @param rows variable in the rows
#' @param cols variable in the columns
#' @param counts Frequency/weight variable for contingency table data. When
#'   specified, the data is treated as already summarized with counts per
#'   combination.
#' @param posthoc Method for p-value adjustment in post-hoc tests. IMPORTANT:
#'   Selecting 'None' DISABLES all pairwise comparisons entirely (not just
#'   adjustment). Unadjusted pairwise testing is not supported to prevent
#'   inappropriate multiple testing. Choose Bonferroni (most conservative), Holm
#'   (less conservative), or FDR (controls false discovery rate) for pairwise
#'   testing.
#' @param sig alpha level for significance testing
#' @param excl Rows with a missing value on the row, column or counts variable
#'   are always excluded before the contingency table is built, because counting
#'   missing values as a category of their own adds a row or column to the table
#'   and changes the degrees of freedom of the chi-square test. This option is
#'   checked by default and is retained so that saved analyses and existing
#'   scripts continue to load; clearing it does not re-admit missing values. A
#'   notice reports how many rows were dropped whenever any were.
#' @param exp show expected values in the table
#' @param plot display plot of standardized residuals
#' @param showResiduals display standardized residuals analysis with
#'   interpretation
#' @param showEducational display educational guidance and explanations
#' @param showDetailedTables display individual 2x2 tables for each pairwise
#'   comparison
#' @param residualsCriterion How the critical value for flagging a cell
#'   residual is chosen. 'Bonferroni-corrected z' divides the significance level
#'   by the number of cells and uses the corresponding normal deviate, so it
#'   accounts for the number of cells tested (2.64 for a 2x3 table, 2.96 for a
#'   4x4). 'Fixed cutoff' uses the value in the 'Residual significance cutoff'
#'   box unchanged.
#' @param residualsCutoff Critical value for identifying significant residuals
#'   (typically 2.0 or 3.0). Used only when 'Residual significance criterion' is
#'   set to 'Fixed cutoff'.
#' @param phiCI calculate bootstrap 95 percent confidence intervals (BCa
#'   method, bias-corrected and accelerated) for the pairwise effect size
#'   sqrt(chi-square / n), which is Cramer's V for a 2xC or Rx2 sub-table and
#'   equals the phi coefficient for a 2x2. Each interval is computed per
#'   comparison and is not adjusted for multiple testing. Note: This is
#'   computationally intensive and may take longer for large tables.
#' @param seed Random seed for the bootstrap confidence intervals, so that the
#'   interval reported for a given table is reproducible. Change it to see how
#'   much the interval depends on the resampling. Used only when bootstrap
#'   confidence intervals are requested.
#' @param testSelection method for selecting statistical test for pairwise
#'   comparisons
#' @param exportResults Export comprehensive analysis results to downloadable
#'   format for further analysis
#' @param showClinicalSummary Display natural-language summary of results for
#'   clinical interpretation
#' @param copyReadySentences Generate copy-ready sentences for clinical
#'   reports
#' @param showAssumptionsCheck Display validation of chi-square test
#'   assumptions
#' @param showGlossary Display glossary of statistical terms with clinical
#'   interpretations
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$todo} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notices} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$chisqTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$assumptionsCheck} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$clinicalSummary} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$educationalOverview} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$weightedDataInfo} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$contingencyTable} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$residualsGuidance} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$residualsAnalysis} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$multipleTestingInfo} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$posthocTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$detailedComparisons} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$exportTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$reportSentences} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$glossaryPanel} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$plot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$chisqTable$asDF}
#'
#' \code{as.data.frame(results$chisqTable)}
#'
#' @export
chisqposttest <- function(
    data,
    rows = NULL,
    cols = NULL,
    counts = NULL,
    posthoc = "bonferroni",
    sig = 0.05,
    excl = TRUE,
    exp = FALSE,
    plot = FALSE,
    showResiduals = FALSE,
    showEducational = FALSE,
    showDetailedTables = FALSE,
    residualsCriterion = "bonferroni",
    residualsCutoff = 2,
    phiCI = FALSE,
    seed = 42,
    testSelection = "auto",
    exportResults = FALSE,
    showClinicalSummary = FALSE,
    copyReadySentences = FALSE,
    showAssumptionsCheck = FALSE,
    showGlossary = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("chisqposttest requires jmvcore to be installed (restart may be required)")

    if ( ! missing(rows)) rows <- jmvcore::resolveQuo(jmvcore::enquo(rows))
    if ( ! missing(cols)) cols <- jmvcore::resolveQuo(jmvcore::enquo(cols))
    if ( ! missing(counts)) counts <- jmvcore::resolveQuo(jmvcore::enquo(counts))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(rows), rows, NULL),
            `if`( ! missing(cols), cols, NULL),
            `if`( ! missing(counts), counts, NULL))

    for (v in rows) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])
    for (v in cols) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- chisqposttestOptions$new(
        rows = rows,
        cols = cols,
        counts = counts,
        posthoc = posthoc,
        sig = sig,
        excl = excl,
        exp = exp,
        plot = plot,
        showResiduals = showResiduals,
        showEducational = showEducational,
        showDetailedTables = showDetailedTables,
        residualsCriterion = residualsCriterion,
        residualsCutoff = residualsCutoff,
        phiCI = phiCI,
        seed = seed,
        testSelection = testSelection,
        exportResults = exportResults,
        showClinicalSummary = showClinicalSummary,
        copyReadySentences = copyReadySentences,
        showAssumptionsCheck = showAssumptionsCheck,
        showGlossary = showGlossary)

    analysis <- chisqposttestClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

